package ntnu.no.backend.model;

import jakarta.persistence.*;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.experimental.SuperBuilder;

import java.util.UUID;

/**
 * An abstract class with shared UUID id field for all entities.
 * This class uses {@link MappedSuperclass} to share {@code id}.
 * All entities in the application should extend this class.
 *
 * @author norakirknes
 * @version 0.1
 * @since 0.1
 */

@NoArgsConstructor
@MappedSuperclass
@Getter
@SuperBuilder
public abstract class BaseEntity {

  /**
   * Unique identifier for the entity autogenerated using
   * {@link GenerationType#UUID} and represented as a UUID for
   * security and global uniqueness. Generated automatically before persisted.
   */
  @Id
  @GeneratedValue(strategy = GenerationType.UUID)
  @Column(name = "id", updatable = false, nullable = false)
  private UUID id;
}
